-- Snapshot exclusivamente sintético, produzido pelo ETL público de referência.
-- Esta carga recria o banco usado pelas consultas do estudo SQL.
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;
CREATE TABLE competencias (
          competencia TEXT PRIMARY KEY, execucao_id TEXT NOT NULL REFERENCES execucoes(execucao_id),
          total_extraido INTEGER NOT NULL CHECK (total_extraido >= 0)
        );
CREATE TABLE etapas (
          execucao_id TEXT NOT NULL REFERENCES execucoes(execucao_id), ordem INTEGER NOT NULL,
          etapa TEXT NOT NULL, entrada INTEGER NOT NULL, saida INTEGER NOT NULL,
          excluidos INTEGER NOT NULL, unidade TEXT NOT NULL,
          PRIMARY KEY (execucao_id, ordem)
        );
CREATE TABLE excluidos (
          competencia TEXT NOT NULL REFERENCES competencias(competencia), "linha_origem" INTEGER NOT NULL, "protocolo_raw" TEXT NOT NULL, "protocolo" TEXT NOT NULL, "protocolo_chave" TEXT NOT NULL, "cliente" TEXT NOT NULL, "revenda" TEXT NOT NULL, "atendente_raw" TEXT NOT NULL, "atendente" TEXT NOT NULL, "inicio_raw" TEXT NOT NULL, "fim_raw" TEXT NOT NULL, "setores" TEXT NOT NULL, "transferencias" TEXT NOT NULL, "avaliacao_raw" TEXT NOT NULL, "inicio" TEXT, "fim" TEXT, "competencia_registro" TEXT, "duracao_horas" REAL, "tma_minutos" REAL, "avaliacao" REAL, "suspeito_automatico" INTEGER NOT NULL CHECK (suspeito_automatico IN (0,1)), "protocolo_duplicado" INTEGER NOT NULL CHECK (protocolo_duplicado IN (0,1)), "motivo_codigo" TEXT,
          PRIMARY KEY (competencia, linha_origem), CHECK (motivo_codigo IS NOT NULL)
        );
CREATE TABLE execucoes (
          execucao_id TEXT PRIMARY KEY, competencia TEXT NOT NULL,
          origem TEXT NOT NULL, origem_sha256 TEXT NOT NULL, configuracao_json TEXT NOT NULL,
          criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
        );
CREATE TABLE ranking (
      competencia TEXT NOT NULL REFERENCES competencias(competencia), "atendente" TEXT, "atendimentos" INTEGER, "horas_total" REAL, "tma_medio_min" REAL, "tma_mediano_min" REAL, "tma_p90_min" REAL, "avaliacao_media" REAL, "avaliacoes" INTEGER, "cobertura_avaliacao" REAL, "automaticos" INTEGER, "pontos_quantidade" REAL, "pontos_tempo" REAL, "pontos_tma" REAL, "pontos_avaliacao" REAL, "nota_final" REAL, "posicao" INTEGER, "elegivel" INTEGER, "premiado" INTEGER,
      PRIMARY KEY (competencia, atendente), UNIQUE (competencia, posicao)
    );
CREATE TABLE validos (
          competencia TEXT NOT NULL REFERENCES competencias(competencia), "linha_origem" INTEGER NOT NULL, "protocolo_raw" TEXT NOT NULL, "protocolo" TEXT NOT NULL, "protocolo_chave" TEXT NOT NULL, "cliente" TEXT NOT NULL, "revenda" TEXT NOT NULL, "atendente_raw" TEXT NOT NULL, "atendente" TEXT NOT NULL, "inicio_raw" TEXT NOT NULL, "fim_raw" TEXT NOT NULL, "setores" TEXT NOT NULL, "transferencias" TEXT NOT NULL, "avaliacao_raw" TEXT NOT NULL, "inicio" TEXT, "fim" TEXT, "competencia_registro" TEXT, "duracao_horas" REAL, "tma_minutos" REAL, "avaliacao" REAL, "suspeito_automatico" INTEGER NOT NULL CHECK (suspeito_automatico IN (0,1)), "protocolo_duplicado" INTEGER NOT NULL CHECK (protocolo_duplicado IN (0,1)), "motivo_codigo" TEXT,
          PRIMARY KEY (competencia, linha_origem), CHECK (motivo_codigo IS NULL), UNIQUE (competencia, protocolo_chave)
        );
COMMIT;
PRAGMA foreign_keys = ON;
